public class SparseMatrix
{
    private readonly Dictionary<(int Row, int Col), double> _cells = new();

    public SparseMatrix(int rows, int cols)
    {
        if (rows <= 0) throw new ArgumentOutOfRangeException(nameof(rows));
        if (cols <= 0) throw new ArgumentOutOfRangeException(nameof(cols));
        Rows = rows;
        Cols = cols;
    }

    public int Rows { get; }
    public int Cols { get; }
    public int NonZero => _cells.Count;

    public double this[int row, int col]
    {
        get
        {
            CheckPosition(row, col);
            return _cells.TryGetValue((row, col), out double v) ? v : 0;
        }
        set
        {
            CheckPosition(row, col);
            if (value == 0) _cells.Remove((row, col));
            else _cells[(row, col)] = value;
        }
    }

    private void CheckPosition(int row, int col)
    {
        if (row < 0 || row >= Rows || col < 0 || col >= Cols)
            throw new ArgumentOutOfRangeException($"({row}, {col}) is outside a {Rows}x{Cols} matrix");
    }

    public static SparseMatrix operator +(SparseMatrix a, SparseMatrix b)
    {
        if (a.Rows != b.Rows || a.Cols != b.Cols) throw new ArgumentException("the matrices have different sizes");
        var result = new SparseMatrix(a.Rows, a.Cols);
        foreach (var ((r, c), v) in a._cells) result[r, c] += v;
        foreach (var ((r, c), v) in b._cells) result[r, c] += v;
        return result;
    }

    public static SparseMatrix operator *(SparseMatrix m, double s)
    {
        var result = new SparseMatrix(m.Rows, m.Cols);
        foreach (var ((r, c), v) in m._cells) result[r, c] = v * s;
        return result;
    }

    public override string ToString() =>
        string.Join("\n", Enumerable.Range(0, Rows).Select(r =>
            string.Join(" ", Enumerable.Range(0, Cols).Select(c => this[r, c].ToString()))));
}

unitTests:
Test("indexer and storage", () =>
{
    var m = new SparseMatrix(2, 3);
    CheckEq(m[1, 2], 0.0);
    m[0, 1] = 1.5;
    m[1, 2] = -2;
    CheckEq(m.NonZero, 2);
    m[0, 1] = 0;
    CheckEq(m.NonZero, 1);
    CheckEq(m.ToString(), "0 0 0\n0 0 -2");
});

Test("bounds", () =>
{
    var m = new SparseMatrix(2, 2);
    CheckThrows<ArgumentOutOfRangeException>(() => { var _ = m[2, 0]; });
    CheckThrows<ArgumentOutOfRangeException>(() => m[0, -1] = 3);
    CheckThrows<ArgumentOutOfRangeException>(() => new SparseMatrix(0, 3));
});

Test("operators", () =>
{
    var a = new SparseMatrix(2, 2);
    var b = new SparseMatrix(2, 2);
    a[0, 0] = 1; a[1, 1] = 2;
    b[0, 0] = -1; b[0, 1] = 4;
    var sum = a + b;
    CheckEq(sum.ToString(), "0 4\n0 2");
    CheckEq(sum.NonZero, 2);
    CheckEq((a * 1.5).ToString(), "1.5 0\n0 3");
    CheckThrows<ArgumentException>(() => { var _ = a + new SparseMatrix(3, 2); });
});

